// Essential Relocation Structure (e.g., based on ELF)
struct RelocationEntry {
    uintptr_t r_offset; // Byte offset within section data to patch
    uint32_t  r_info;   // Combined: Target Symbol Index | Relocation Type
};

// Common Relocation Types define the formula:
// S = Symbol Value (Final assigned address)
// A = Addend (Existing instruction/data value)
// P = Address of the location being relocated

// Linker/Loader Operation (e.g., Absolute 32-bit relocation: R_386_32)
void patch_memory(RelocationEntry R, uintptr_t S_Addr) {
    uint32_t* P = (uint32_t*)R.r_offset; // Ptr to instruction/data word

    // A is the existing instruction value
    uint32_t A = *P;

    // Apply relocation formula: Target = S + A
    *P = (uint32_t)(S_Addr + A);
}

// PC-Relative Types use: Target = S + A - P
